import{_ as a,o,c,ae as t}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"伪代码版本 / C++ 版本","description":"","frontmatter":{},"headers":[],"relativePath":"数据结构/代码实现/伪代码版本/c++版本/index.md","filePath":"数据结构/代码实现/伪代码版本/c++版本/index.md","lastUpdated":1776859928000}'),d={name:"数据结构/代码实现/伪代码版本/c++版本/index.md"};function p(r,e,i,n,l,s){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="伪代码版本-c-版本" tabindex="-1">伪代码版本 / C++ 版本 <a class="header-anchor" href="#伪代码版本-c-版本" aria-label="Permalink to &quot;伪代码版本 / C++ 版本&quot;">​</a></h1><blockquote><p><strong>用途</strong>: 考卷手写（推荐）。不含 <code>main()</code>，不可单独编译运行。</p></blockquote><h2 id="语法风格" tabindex="-1">语法风格 <a class="header-anchor" href="#语法风格" aria-label="Permalink to &quot;语法风格&quot;">​</a></h2><ul><li><p>C++ 引用 <code>&amp;</code> 风格: 参数传递用引用，避免繁琐的二级指针</p></li><li><p>408 阅卷标准中明确允许使用 <code>&amp;</code> 引用及简单 STL (<code>&lt;stack&gt;</code>, <code>&lt;queue&gt;</code>)</p></li><li><p>不使用 C++11/14/17 等新特性</p></li></ul><h2 id="文件清单" tabindex="-1">文件清单 <a class="header-anchor" href="#文件清单" aria-label="Permalink to &quot;文件清单&quot;">​</a></h2><p>| 文件 | 内容 |</p><p>|:---|:---|</p><p>| <code>01_线性表.cpp</code> | 顺序表增删 / 单链表头插尾插 (引用风格) |</p><p>| <code>02_栈和队列.cpp</code> | 顺序栈 / 循环队列(引用风格) |</p><p>| <code>03_树与层序遍历.cpp</code> | 三序递归+非递归 / 层序(STL queue) / AVL判别 / 并查集 |</p><p>| <code>04_排序算法.cpp</code> | 八大排序伪代码 + 归并 + Partition变式 |</p><p>| <code>05_串与查找.cpp</code> | KMP(next+nextval) / 折半查找 |</p><p>| <code>06_图的核心算法.cpp</code> | DFS/BFS(STL queue) / Dijkstra |</p><h2 id="为什么推荐-c-版本" tabindex="-1">为什么推荐 C++ 版本? <a class="header-anchor" href="#为什么推荐-c-版本" aria-label="Permalink to &quot;为什么推荐 C++ 版本?&quot;">​</a></h2><p>考场上 C++ 的引用 <code>&amp;</code> 让参数传递清晰一目了然，免去 C 中大量的 <code>*L</code>、<code>(*L)-&gt;next</code> 等解引用操作，<strong>降低手写出错概率，节省宝贵时间</strong>。</p>',15)])])}const h=a(d,[["render",p]]);export{u as __pageData,h as default};
